package com.example.data

data class AllahName(
    val id: Int,
    val name: String,
    val meaning: String,
    val explanation: String
)

object NamesOfAllahData {
    val hadithVirtue: String = "قال رسول الله ﷺ: «إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا مِائَةً إِلاَّ وَاحِدًا، مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ» (متفق عليه)"

    val names: List<AllahName> = listOf(
        AllahName(1, "الرَّحْمَنُ", "المنعم بجلائل النعم، ذو الرحمة العامة الشاملة لجميع الخلائق في الدنيا.", "الذي وسعت رحمته كل شيء، وعمّ بفضله وإحسانه جميع خلقه مؤمنهم وكافرهم."),
        AllahName(2, "الرَّحِيمُ", "المنعم بدقائق النعم، ذو الرحمة الخاصة بالمؤمنين في الآخرة.", "الذي يرحم عباده المؤمنين برحمته الخاصة فيهديهم في الدنيا ويكرمهم في الآخرة بالجنة."),
        AllahName(3, "الْمَلِكُ", "المتصرف في ملكه كيف يشاء، المتصرف في الأكوان بالأمر والنهي.", "صاحب الملك التام والسيادة المطلقة، مستغنٍ بذاته عن كل شيء وكل شيء مفتقر إليه."),
        AllahName(4, "الْقُدُّوسُ", "المنزه عن كل عيب ونقص، الطاهر من كل دنس.", "المقدس المطهر عن مشابهة الحوادث، المبرأ من الآفات والعيوب التي تعتري المخلوقات."),
        AllahName(5, "السَّلاَمُ", "السالم من النقائص والعيوب، وناشر السلام والأمان بين خلقه.", "الذي سلمت ذاته وصفاته من كل عيب، ومنه يُستمد الأمان والسكينة."),
        AllahName(6, "الْمُؤْمِنُ", "المصدق لرسله بالمعجزات، الذي يؤمّن أولياءه من عذابه وخوفه.", "الواهب للأمن والأمان والطمأنينة، والمصدق للمؤمنين بوعده الحق."),
        AllahName(7, "الْمُهَيْمِنُ", "الرقيب الشاهد على خلقه، الحافظ لكل شيء القائم عليه.", "المطلع على خفايا الأمور وخبايا الصدور، لا يغيب عن علمه وحفظه مثقال ذرة."),
        AllahName(8, "الْعَزِيزُ", "القوي الغالب الذي لا يُغلب، المنيع الذي لا يُنال.", "الذي لا يقهره قاهر، ولا يغلبه غالب، قهر كل المخلوقات بعزته وكبريائه."),
        AllahName(9, "الْجَبَّارُ", "الذي يجبر قلوب المنكسرين، ويقهر الجبابرة بعظمته.", "الذي ينفذ مشيئته في خلقه رغماً عنهم، ويجبر الكسير ويغني الفقير ويسهل العسير."),
        AllahName(10, "الْمُتَكَبِّرُ", "المتعالي عن صفات الخلق، ذو الكبرياء والعظمة التامة.", "الذي تكبر عن كل سوء وظلم، واختص برداء الكبرياء والعظمة."),
        AllahName(11, "الْخَالِقُ", "المبدع للأشياء على غير مثال سابق، الموجد لها من العدم.", "الذي أوجد جميع الكائنات وقدّر وجودها بحكمته البالغة."),
        AllahName(12, "الْبَارِئُ", "المميّز للمخلوقات بعضها عن بعض بصورها وهيئاتها.", "الذي خلق الخلق بريئين من التفاوت والتناقض في الخلق والإتقان."),
        AllahName(13, "الْمُصَوِّرُ", "المعطي لكل مخلوق صورته وشكله وهيئته الخاصة.", "الذي صوّر الأجنة في الأرحام، وشكّل المخلوقات بأجمل وأحكم نظام."),
        AllahName(14, "الْغَفَّارُ", "الكثير المغفرة، الساتر للذنوب في الدنيا والماحي لها في الآخرة.", "الذي يغفر ذنوب عباده مهما تعاظمت إذا أنابوا واستغفروا."),
        AllahName(15, "الْقَهَّارُ", "الغالب لجميع المخلوقات، الخاضع لعظمته كل شيء.", "الذي ذلت له الرقاب وعنت له الوجوه، ولا يخرج كائن عن قبضة سلطانه."),
        AllahName(16, "الْوَهَّابُ", "الكثير العطايا والمنح بلا عوض ولا غرض.", "الذي يجود بالنعم والخيرات بغير حساب وبلا انقطاع."),
        AllahName(17, "الرَّزَّاقُ", "الخالق للأرزاق والمتكفل بإيصالها إلى جميع خلقه.", "الذي يرزق الأبدان بالأقوات والأرواح بالمعارف والإيمان."),
        AllahName(18, "الْفَتَّاحُ", "الحاكم بين عباده بالعدل، والفاتح لأبواب رحمته ورزقه.", "الذي يفتح المغاليق ويسهل الصعاب ويحكم بالحق والعدل."),
        AllahName(19, "الْعَلِيمُ", "المحيط بكل شيء علماً ظاهراً وباطناً سراً وعلانية.", "الذي يعلم ما كان وما يكون وما لم يكن لو كان كيف يكون."),
        AllahName(20, "الْقَابِضُ", "المضيق للرزق بحكمته، القابض للأرواح عند أجلها.", "يقبض الأرزاق والقلوب بحكمة وابتلاء كما يشاء."),
        AllahName(21, "الْبَاسِطُ", "الموسع للأرزاق بفضله ورحمته، الناشر لنعمه.", "يبسط الرزق لمن يشاء بفضله ويبعث الطمأنينة والأمل."),
        AllahName(22, "الْخَافِضُ", "المذل لأعدائه والواضع للظالمين والمتكبرين.", "يخفض من تكبر وعصى وتجبر عن قبول الحق."),
        AllahName(23, "الرَّافِعُ", "المعلي لأوليائه وأهل طاعته بالعلم والتقوى.", "يرفع درجات المؤمنين والصالحين في الدنيا والآخرة."),
        AllahName(24, "الْمُعِزُّ", "الواهب للعزة والكرامة والتمكين لأوليائه.", "يعز من أطاعه وتمسك بدينه، فالعزة لله ولرسوله وللمؤمنين."),
        AllahName(25, "الْمُذِلُّ", "الموقع للهوان والخزي على أعدائه والمشركين.", "يذل من عصاه واستكبر عن عبادته بالخسران والخذلان."),
        AllahName(26, "السَّمِيعُ", "المدرك للأصوات كلها جليها وخفيها، مجيب الدعاء.", "يسمع دبيب النملة السوداء على الصخرة الملساء في الليلة الظلماء."),
        AllahName(27, "الْبَصِيرُ", "المبصر لكل المبصرات والمحيط بدقائق الأشياء وخفاياها.", "يرى ما تحت الثرى، مطلع على أفعال العباد وضمائرهم."),
        AllahName(28, "الْحَكَمُ", "القاضي العدل الذي لا راد لقضائه ولا معقب لحكمه.", "يفصل بين الخلائق بالحق، وحكمه العدل المطلق."),
        AllahName(29, "الْعَدْلُ", "المنزه عن الظلم والجور، المنصف في كل أفعاله وأقداره.", "وضع كل شيء في موضعه اللائق بحكمة وكمال وعدالة."),
        AllahName(30, "اللَّطِيفُ", "الرفيق بعباده، الموصل للإحسان إليهم برفق وخفاء.", "يعلم دقائق المصالح ويوصلها إلى مستحقيها بلطف لا يُدرك."),
        AllahName(31, "الْخَبِيرُ", "العالم بدقائق الأمور وبواطنها وخفايا الصدور.", "لا يعزب عنه مثقال ذرة، عليم بحقائق الأشياء وما تخفيه الصدور."),
        AllahName(32, "الْحَلِيمُ", "الصبور الذي لا يعاجل بالعقوبة مع كمال قدرته عليها.", "يرى معصية العاصين فيمهلهم للتوبة ولا يستفزه الغضب."),
        AllahName(33, "الْعَظِيمُ", "الذي جاوزت عظمته حدود العقول والأفهام.", "له كمال الذات والصفات، فلا شيء أعظم منه ولا أجل."),
        AllahName(34, "الْغَفُورُ", "الواسع المغفرة والستر، الماحي لذنوب عباده.", "يغفر الذنوب الكبار ويستر العيوب ولا يفضح عباده التائبين."),
        AllahName(35, "الشَّكُورُ", "المجازي على العمل القليل بالثواب الجزيل والكبير.", "يقبل القليل من العمل الصالح ويعطي عليه الأجر العظيم بلا انقطاع."),
        AllahName(36, "الْعَلِيُّ", "المتعالي في ذاته وصفاته وقدره وقهره فوق كل مخلوق.", "العلو المطلق لله تعالى: علو الذات وعلو القدر وعلو القهر."),
        AllahName(37, "الْكَبِيرُ", "الذي كل شيء دونه صغير، ذو الكبرياء والجلال.", "أكبر من كل شيء، وأعظم من كل ما يخطر بالبال."),
        AllahName(38, "الْحَفِيظُ", "الحافظ لسمواته وأرضه وخلقه، والمسجل لأعمال العباد.", "يحفظ عباده من المكاره ويحفظ عليهم أعمالهم ليجازيهم بها."),
        AllahName(39, "الْمُقِيتُ", "المتكفل بأقوات الخلائق، المقتدر الحفيظ.", "خالق الأقوات وموصلها للحيوان والإنسان ومقدرها بحكمة."),
        AllahName(40, "الْحَسِيبُ", "الكافي لعباده، والمحاسب لهم على أعمالهم بدقة.", "كافٍ لمن توكل عليه، ومحصٍ لأعمال الخلائق يوم الدين."),
        AllahName(41, "الْجَلِيلُ", "الموصوف بنعوت الجلال والعظمة والكمال.", "صاحب المهابة والجلال والكبرياء التي تملأ القلوب تعظيماً."),
        AllahName(42, "الْكَرِيمُ", "الكثير الخير، الجواد الذي يعطي قبل السؤال وبلا مقابل.", "يعفو إذا قدر، ويفي إذا وعد، ويزيد على نهاية الأمل."),
        AllahName(43, "الرَّقِيبُ", "المطلع الحارس الذي لا يغفل عنه مثقال ذرة في الكون.", "يراقب الحركات والسكنات وخطرات النفوس والخواطر."),
        AllahName(44, "الْمُجِيبُ", "المستجيب لدعاء الداعين وسؤال السائلين.", "يقابل دعوة عبده بالإجابة، وسؤاله بالعطاء، وفق ما يصلحه."),
        AllahName(45, "الْوَاسِعُ", "المحيط بكل شيء سعة في علمه ورحمته ورزقه ومغفرته.", "وسعت رحمته كل شيء، ووسع كرسيه السماوات والأرض."),
        AllahName(46, "الْحَكِيمُ", "الواضع للأشياء في مواضعها المتقنة بحكمة بالغة.", "منزه عن العبث، كل أفعاله وأوامره مبنية على غاية الإحكام."),
        AllahName(47, "الْوَدُودُ", "المحب لعباده المؤمنين والمحبوب في قلوب أوليائه.", "يتودد إلى عباده بنعمه ويثبت محبته في قلوب أوليائه المقربين."),
        AllahName(48, "الْمَجِيدُ", "الشريف الذات، الجميل الأفعال، الجزيل العطايا والمنن.", "البالغ المنتهى في الشرف والمجد والفضل والكرم."),
        AllahName(49, "الْبَاعِثُ", "الباعث للرسل بالهدى، والباعث للأموات من القبور للجزاء.", "يحيي الموتى للحساب ويبعث الهمم إلى نيل الدرجات العلى."),
        AllahName(50, "الشَّهِيدُ", "المطلع على كل شيء، الشاهد على سر وعلانية عباده.", "لا يغيب عنه شيء من أفعال العباد وأقوالهم."),
        AllahName(51, "الْحَقُّ", "الثابت وجوده الذي لا ريب فيه، الصادق في وعده ووعيده.", "الموجود حقاً، الذي كل ما عداه هالك إلا وجهه الكريم."),
        AllahName(52, "الْوَكِيلُ", "المفوَّض إليه أمر الخلائق، الكافي لمن توكل عليه.", "المتكفل بأرزاق العباد ومصالحهم، خير من يُعتمد عليه."),
        AllahName(53, "الْقَوِيُّ", "البالغ الغاية في القوة والقدرة التي لا يلحقها وهن.", "قادر على إنفاذ أمره بلا ضعف ولا معجز يمنعه."),
        AllahName(54, "الْمَتِينُ", "الشديد القوة الذي لا تتعب قدرته ولا تنقص.", "ثابت القدرة، منيع الشأن، لا تنقطع عزيمته ولا يعتريه فتور."),
        AllahName(55, "الْوَلِيُّ", "المتولي لأمور خلقه، الناصر والمعين لأوليائه المؤمنين.", "يحب عباده المؤمنين، ينصرهم ويؤيدهم ويهديهم إلى الصراط المستقيم."),
        AllahName(56, "الْحَمِيدُ", "المستحق للحمد والثناء التام بذاته وصفاته وأفعاله.", "محمود على كل حال، في الشدة والرخاء، له الأسماء الحسنى."),
        AllahName(57, "الْمُحْصِي", "العالم بمقادير الأشياء وعدّها بدقة بالغة.", "أحصى كل شيء عدداً وعلم أوزان الجبال ومثاقيل الذرات."),
        AllahName(58, "الْمُبْدِئُ", "المبتدئ لخلق الكائنات من العدم أول مرة.", "أنشأ الخلائق كلها إبداعاً وابتداءً من غير مثال سابق."),
        AllahName(59, "الْمُعِيدُ", "المعيد للخلق بعد فنائهم إلى الحياة للحساب.", "يعيد الأجساد كما بدأها أول مرة ليوفي الصابرين أجورهم."),
        AllahName(60, "الْمُحْيِي", "الواهب للحياة لمن يشاء من الجماد والنطف والخلائق.", "يحيي الأرض بعد موتها ويبعث الحياة في الأرواح والأبدان."),
        AllahName(61, "الْمُمِيتُ", "المقدِّر للموت على الأحياء عند انقضاء آجالهم.", "يسلب الحياة عمن يشاء بحكمته وأجله المسمى."),
        AllahName(62, "الْحَيُّ", "الدائم الباقي بالحياة الكاملة الأزلية الأبدية بلا زوال.", "له الحياة التامة التي لا يعتريها موت ولا نوم ولا سنة."),
        AllahName(63, "الْقَيُّومُ", "القائم بنفسه المقيم لغيره، المستغني عن كل سواه.", "قام بتدبير وحفظ السماوات والأرض وما بينهما."),
        AllahName(64, "الْوَاجِدُ", "الغني الذي لا يعوزه شيء، ولا يضل عنه مطلوب.", "واجد لكل ما يريده ومتحقق لكل أمر بمشيئته."),
        AllahName(65, "الْمَاجِدُ", "ذو الشرف العظيم والمجد الباذخ والسخاء الواسع.", "له الكبرياء والمجد والجلال الذي يبهر الألباب."),
        AllahName(66, "الْوَاحِدُ", "المنفرد بذاته وصفاته وأفعاله بلا شريك ولا مثيل.", "لا شريك له في ملكه ولا إله غيره في أرضه وسمائه."),
        AllahName(67, "الأَحَدُ", "الفرد الأحد الذي لا يتجزأ ولا يتعدد، الصمد.", "أحد في ألوهيته وربوبيته وأسمائه وصفاته."),
        AllahName(68, "الصَّمَدُ", "المقصود في الحوائج كلها، المستغني عن الطعام والشراب.", "تلجأ إليه جميع الخلائق في حاجاتها وفقرها وكروبها."),
        AllahName(69, "الْقَادِرُ", "المتمكن من فعل كل ما يشاء بحكمته وإرادته.", "إذا أراد شيئاً فإنما يقول له كن فيكون."),
        AllahName(70, "الْمُقْتَدِرُ", "التام القدرة الذي لا يمتنع عليه شيء أصلاً.", "مقتدر على نصر أوليائه وقهره للجبابرة وقضاء أقدار الكون."),
        AllahName(71, "الْمُقَدِّمُ", "المقدِّم لمن يشاء بطاعته ورحمته في المراتب.", "يقدم ما تقتضي حكمته تقديمه من الأقدار والأشخاص والأزمان."),
        AllahName(72, "الْمُؤَخِّرُ", "المؤخر لمن يشاء بعدله، المؤخر للأشياء إلى آجالها.", "يؤخر ما يشاء بحكمته لحين موعده المقدّر."),
        AllahName(73, "الأَوَّلُ", "السابق لكل شيء، الذي ليس قبله شيء أزلياً.", "الذي كان ولم يكن شيء قبله سبحانه وتعالى."),
        AllahName(74, "الآخِرُ", "الباقي بعد فناء خلقه، الذي ليس بعده شيء أبدياً.", "يبقى وجه ربك ذو الجلال والإكرام بعد فناء كل مخلوق."),
        AllahName(75, "الظَّاهِرُ", "العالي فوق كل شيء بالغلبة، الظاهر بآياته ودلائله.", "الذي دلت على وجوده وقدرته كل الكائنات والعقول."),
        AllahName(76, "الْبَاطِنُ", "المحتجب عن أبصار خلقه، العالم بخفايا وأسرار الأمور.", "لا تحيط به الأبصار، ومطلع على أدق الأسرار."),
        AllahName(77, "الْوَالِي", "المتولي لتدبير شؤون مملكته وسائر خلقه.", "سيد الكون والمتصرف فيه بالحفظ والنصرة والتدبير."),
        AllahName(78, "الْمُتَعَالِي", "المتنزه عن كل سمات النقص والمشابهة لخلقه.", "جل عن إدراك الخلائق، وتعالى عن صفات المحدثات."),
        AllahName(79, "الْبَرُّ", "الكثير الإحسان واللطف، الصادق في وعده لصلحاء عباده.", "عطوف رحيم واسع الفضل والبر على خلقه."),
        AllahName(80, "التَّوَّابُ", "القابل لتوبة التائبين الميسر لها والمغفرة بعدها.", "يفرح بتوبة عبده إذا تاب ويغفر له الذنوب المتكررة."),
        AllahName(81, "الْمُنْتَقِمُ", "المعاقب للظالمين والمجرمين بعد إنذارهم وإمهالهم.", "يقصم الظالمين ويأخذهم أخذ عزيز مقتدر إن تمادوا."),
        AllahName(82, "العَفُوُّ", "الماحي للذنوب والصفوح عن الزلات كأن لم تكن.", "أبلغ من الغفور، لأنه يمحو أثر الذنب كلياً من الصحيفة."),
        AllahName(83, "الرَّؤُوفُ", "الشديد الرحمة والشفقة بعباده، اللطيف بهم.", "رأفته تسبق غضبه، ييسر العسير ويدرأ المشقة."),
        AllahName(84, "مَالِكُ الْمُلْكِ", "المتصرف المطلق في ملكه يؤتي الملك من يشاء.", "له الملك كله، يعز ويذل، ويبسط ويقبض كما يشاء."),
        AllahName(85, "ذُو الْجَلاَلِ وَالإِكْرَامِ", "المستحق للتعظيم والإجلال، المفيض للإكرام والفضل.", "صاحب العظمة التي يُهاب بها، والإحسان الذي يُشكر عليه."),
        AllahName(86, "الْمُقْسِطُ", "العادل في حكمه المنصف للمظلوم من الظالم.", "يأخذ للمظلوم حقه حتى لا يضيع عند الله مثقال حبة."),
        AllahName(87, "الْجَامِعُ", "الجامع للخلائق يوم القيامة للحساب، والجامع للمتفرقات.", "يجمع بين الأولين والآخرين في يوم لا ريب فيه."),
        AllahName(88, "الْغَنِيُّ", "المستغني عن كل ما سواه، والكل مفتقر إليه.", "لا تنفعه طاعة الطائعين ولا تضره معصية العاصين."),
        AllahName(89, "الْمُغْنِي", "المعطي للغنى والكفاية لمن يشاء من عباده.", "يسد حاجة الفقراء ويغني القلوب بالإيمان والقناعة."),
        AllahName(90, "الْمَانِعُ", "الذي يمنع ما يشاء بحكمته لحماية عبده أو امتحانه.", "منعه عطاء ودفع للضرر بحكمته التي لا يدركها البشر."),
        AllahName(91, "الضَّارُّ", "المقدّر للضر والبلاء على من يشاء لحكمة بالغة.", "لا يقع ضر إلا بإذنه لحكمة وابتلاء وتمحيص للذنوب."),
        AllahName(92, "النَّافِعُ", "الخالق للنفع والخير والبركة في الكون.", "كل خير ونعمة وصحة وهداية هي من فضله وحده."),
        AllahName(93, "النُّورُ", "المضيء للسماوات والأرض والهادي لقلوب المؤمنين.", "الله نور السماوات والأرض، به اهتدت القلوب والأنفس."),
        AllahName(94, "الْهَادِي", "المرشد لخلقه إلى مصالحهم والمهدي لقلوبهم إلى التوحيد.", "يهدي من يشاء إلى صراط مستقيم ويبين معالم الحق."),
        AllahName(95, "الْبَدِيعُ", "الذي خلق الكون على طراز فريد لا نظير له ولا مثيل.", "بديع السماوات والأرض في إتقانها وجمالها بلا مثال سابق."),
        AllahName(96, "الْبَاقِي", "الدائم الوجود بعد فناء المخلوقات الذي لا ينتهي.", "أبدي لا يلحقه فناء ولا زوال، كل شيء هالك إلا وجهه."),
        AllahName(97, "الْوَارِثُ", "الباقي بعد ذهاب المالكين، الذي يرث الأرض ومن عليها.", "إليه يرجع الملك كله بعد فناء الخلائق أجمعين."),
        AllahName(98, "الرَّشِيدُ", "المرشد للحق والحكيم في تدبيره الذي لا يضل.", "أفعاله سديدة وأقواله رشيدة يضع كل شيء في موضعه."),
        AllahName(99, "الصَّبُورُ", "الذي لا يستعجل العقوبة على العصاة مع كمال قدرته.", "يصبر على أذى المشركين وإمهالهم لعلهم يرجعون.")
    )
}
